-- A photo or video whose row goes leaves its file to the sweep, which removes it from the store.
CREATE FUNCTION queue_file_removal() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO photo_removal (store_key, queued_at) VALUES (OLD.store_key, now()) ON CONFLICT DO NOTHING;
  RETURN OLD;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER "draft_photo_removed" AFTER DELETE ON "draft_photo" FOR EACH ROW EXECUTE FUNCTION queue_file_removal();
--> statement-breakpoint
CREATE TRIGGER "draft_video_removed" AFTER DELETE ON "draft_video" FOR EACH ROW EXECUTE FUNCTION queue_file_removal();
